import{_ as r,a as s}from"./chunks/remote-storage.CsnAD74x.js";import{_ as n,C as i,o as l,c as d,a2 as t,j as c,a,E as h}from"./chunks/framework.Dx-TCpNt.js";const v=JSON.parse('{"title":"Remote Storage & Backup","description":"Your images can live on another disk, a NAS share or a WebDAV server while annotations stay in the local data/ folder. This page covers how remote…","frontmatter":{"description":"Your images can live on another disk, a NAS share or a WebDAV server while annotations stay in the local data/ folder. This page covers how remote…"},"headers":[],"relativePath":"guide/remote.md","filePath":"guide/remote.md","lastUpdated":1794841797000}'),p={name:"guide/remote.md"};function g(u,e,m,f,b,k){const o=i("Badge");return l(),d("div",null,[e[2]||(e[2]=t('<h1 id="remote-storage-backup" tabindex="-1">Remote Storage &amp; Backup <a class="header-anchor" href="#remote-storage-backup" aria-label="Permalink to &quot;Remote Storage &amp; Backup&quot;">​</a></h1><p>Your images can live on another disk, a NAS share or a WebDAV server while annotations stay in the local <code>data/</code> folder. This page covers how remote libraries behave, what happens when the network sulks, and how backups work.</p><h2 id="the-problem-it-solves" tabindex="-1">The problem it solves <a class="header-anchor" href="#the-problem-it-solves" aria-label="Permalink to &quot;The problem it solves&quot;">​</a></h2><p>A manga library is often much bigger than the disk you want the app to index — or it already lives on a NAS. Copying tens of thousands of images into <code>raw/</code> is wasteful. Annotations, meanwhile, are tiny and must never be lost just because the Wi-Fi blinked.</p><p>KomaYomi separates the two: <strong>images are read remotely on demand, annotations are written locally.</strong></p><h2 id="setting-up-a-remote-library" tabindex="-1">Setting up a remote library <a class="header-anchor" href="#setting-up-a-remote-library" aria-label="Permalink to &quot;Setting up a remote library&quot;">​</a></h2><ol><li>Open <strong>Backup / restore</strong> in the sidebar.</li><li>In <strong>Remote assets / network storage</strong>, click <strong>Add a remote folder</strong>.</li><li>Fill in the target:</li></ol><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>Label shown in the dialog.</td></tr><tr><td><strong>Type</strong></td><td>Local folder, Network drive / UNC, or WebDAV.</td></tr><tr><td><strong>Folder path</strong></td><td>e.g. <code>D:\\manga</code> or <code>\\\\nas\\share\\manga</code> (local / network).</td></tr><tr><td><strong>WebDAV URL</strong>, <strong>Username</strong>, <strong>Password</strong></td><td>WebDAV credentials.</td></tr><tr><td><strong>Read-only</strong></td><td>Mark the source as read-only so the app never writes to it.</td></tr></tbody></table><ol start="4"><li>Click <strong>Test connection</strong>. The dialog reports <em>Online</em> / <em>Offline</em> and whether the target is read-only.</li><li>Click <strong>Sync remote folder tree</strong>.</li></ol><h3 id="what-the-sync-does" tabindex="-1">What the sync does <a class="header-anchor" href="#what-the-sync-does" aria-label="Permalink to &quot;What the sync does&quot;">​</a></h3><p>The app walks the remote folder and creates <strong>zero-byte placeholder files</strong> in a local mirror (<code>data/cache/remote/tree/</code>). The normal library scanner and folder rules then run over that mirror, so remote volumes appear in the sidebar exactly like local ones, with the same volume → language → chapter grouping.</p><ul><li>Only image extensions are mirrored: <code>.jpg</code>, <code>.jpeg</code>, <code>.png</code>, <code>.webp</code>, <code>.gif</code>, <code>.avif</code>, <code>.bmp</code>.</li><li>The walk is limited to 10 levels deep and <strong>20,000 files</strong>; hitting the limit reports “file limit reached” and stops.</li><li>Folders that cannot be read are counted and reported, without aborting the sync.</li><li>Syncing again replaces the mirror; annotations are unaffected.</li></ul><h2 id="on-demand-loading-and-caching" tabindex="-1">On-demand loading and caching <a class="header-anchor" href="#on-demand-loading-and-caching" aria-label="Permalink to &quot;On-demand loading and caching&quot;">​</a></h2><p>When you open a page:</p><ol><li>The app checks the local cache for the original file.</li><li>If it is missing, the file is fetched from the remote source.</li><li>The bytes are written to <code>data/cache/remote/files/</code>, content-addressed per provider and path.</li><li>Thumbnails are generated from the cached original.</li></ol><p>There is no “download the whole library” step. Only pages you actually open are fetched.</p><table tabindex="0"><thead><tr><th>Control</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Cache n MB / limit MB (m files)</strong></td><td>Current cache usage.</td></tr><tr><td><strong>Cache limit (MB)</strong></td><td>Upper bound; default <strong>512 MB</strong>, any positive value up to 100,000.</td></tr><tr><td><strong>Clear image cache</strong></td><td>Deletes cached remote originals and thumbnails; safe to use, they are re-fetched.</td></tr></tbody></table><p>When the cache exceeds its limit, the least-recently-used files are evicted until usage falls below <strong>90%</strong> of the cap.</p><h2 id="offline-behaviour" tabindex="-1">Offline behaviour <a class="header-anchor" href="#offline-behaviour" aria-label="Permalink to &quot;Offline behaviour&quot;">​</a></h2><p>The network is allowed to disappear:</p><table tabindex="0"><thead><tr><th>Situation</th><th>Result</th></tr></thead><tbody><tr><td>Page already cached</td><td>Opens normally, offline.</td></tr><tr><td>Page not cached, remote offline</td><td>The image request fails with HTTP <strong>503</strong> <code>ERR_REMOTE_UNAVAILABLE</code>; the UI shows an error instead of hanging.</td></tr><tr><td>Thumbnail of an uncached page, remote offline</td><td>HTTP <strong>502</strong> <code>ERR_THUMB_FETCH_FAILED</code>.</td></tr><tr><td>Annotations, notes, panels</td><td>Always local; you can keep editing pages whose images are cached.</td></tr></tbody></table><p>If a save fails — offline, a restarting server, a 5xx — the page document is not lost. It goes into a local <strong>outbox</strong> in browser storage and is replayed later:</p><ul><li>One entry per page; a newer write replaces the older one, so replay is safe to repeat.</li><li>Capped at 100 pages. If browser storage fills up, pasted screenshots are dropped first so the note text survives.</li><li>Replay runs on load, when the browser reconnects, every 30 seconds while anything is pending, and on demand from the pending-count chip.</li><li>Replay stops at the first failure to keep the version history in order, and tries again later.</li></ul><p>This is a browser-side buffer, not a remote sync: every write still lands in the local <code>data/</code> folder.</p><div class="tip custom-block"><p class="custom-block-title">Practical offline use</p><p>Before going offline, open the pages you plan to study. They stay readable because the originals and thumbnails are cached. The cache limit determines how much you can carry.</p></div><h2 id="passwords-and-credentials" tabindex="-1">Passwords and credentials <a class="header-anchor" href="#passwords-and-credentials" aria-label="Permalink to &quot;Passwords and credentials&quot;">​</a></h2><ul><li>Passwords are <strong>not</strong> stored in <code>storage.json</code>.</li><li>They are encrypted with <strong>AES-256-GCM</strong> into <code>data/secrets.json.enc</code>, using a per-install key file <code>data/.secret.key</code> created with mode <code>0600</code>.</li><li>A copied or synced <code>data/</code> folder therefore does not leak the password, and the UI never shows it back — leave the password field blank to keep the saved value.</li><li>Passwords are <strong>excluded from backups</strong>.</li></ul><h2 id="backup-targets" tabindex="-1">Backup targets <a class="header-anchor" href="#backup-targets" aria-label="Permalink to &quot;Backup targets&quot;">​</a></h2><p>The same dialog lists <strong>Backup targets</strong>. A target is where a backup ZIP is uploaded:</p><ol><li><strong>Add a backup target</strong> and choose local folder, network drive or WebDAV.</li><li><strong>Back up to this target</strong> builds a ZIP of <code>data/</code> and uploads it to <code>backups/backup-&lt;timestamp&gt;.zip</code> under that target.</li><li>The dialog reports the target, file name and size when it finishes.</li></ol><p>Any configured source or target can be tested with <strong>Test connection</strong>; the ones that are offline are reported.</p><h2 id="manual-backup-and-restore" tabindex="-1">Manual backup and restore <a class="header-anchor" href="#manual-backup-and-restore" aria-label="Permalink to &quot;Manual backup and restore&quot;">​</a></h2><figure class="shot"><img src="'+r+'" alt="Backup and restore dialog with create backup, choose a backup file and the inspected archive summary"><figcaption>The backup dialog. A backup is inspected before restoring, so you can see how many pages, notes and templates it contains before anything is overwritten.</figcaption></figure><ul><li><strong>Create and download a backup</strong> produces a ZIP of <code>data/</code>: pages, templates, presets, layouts, <code>library.json</code> and a <code>.backup-meta.json</code>. Thumbnail caches and temporary files are excluded.</li><li><strong>Choose a backup file…</strong> inspects the ZIP first and reports how many pages, notes, templates and presets it contains, and which volumes are involved.</li><li>Restoring <strong>overwrites same-named files</strong> under <code>data/</code> but does not delete pages absent from the backup. A snapshot of the current data is written before the restore.</li></ul><p>See <a href="/KomaYomi-docs/remote-backup">Remote Storage &amp; Backup (reference)</a> for the file-level contract and the exact storage JSON.</p><h2 id="current-limitations" tabindex="-1">Current limitations <a class="header-anchor" href="#current-limitations" aria-label="Permalink to &quot;Current limitations&quot;">​</a></h2>',36)),c("p",null,[e[0]||(e[0]=a("The following remain ",-1)),h(o,{type:"warning",text:"Planned"}),e[1]||(e[1]=a(":",-1))]),e[3]||(e[3]=t('<ul><li>Cloud providers other than WebDAV (no Dropbox / Google Drive / S3 integration).</li><li>Automatic upload of scheduled backups to a remote target: <strong>Scheduled backups</strong> write local <code>exports/auto-backup-*.zip</code> archives, and moving them to a remote target is still manual.</li></ul><figure class="shot"><img src="'+s+'" alt="Remote storage section of the Backup / restore dialog: WebDAV source, cache usage and a backup target"><figcaption>Remote storage in Backup / restore: a WebDAV source, cache usage and a backup target.</figcaption></figure><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><ul><li><strong>The remote volume does not appear.</strong> Run <strong>Sync remote folder tree</strong>; the mirror is what the library scans. Check the file limit and skipped-folder count in the result.</li><li><strong>Every page shows a 503.</strong> The remote is offline and the page was never cached. Reconnect, then reopen the page.</li><li><strong>Disk usage keeps growing.</strong> The cache cap is 512 MB by default; raise it deliberately, or clear the cache when you switch libraries.</li><li><strong>A backup is missing a password.</strong> That is by design; re-enter the password after restoring on another machine.</li><li><strong>A network path works in Explorer but not here.</strong> Network drives must be reachable from the account that runs the app — this matters for a service or a different desktop user.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/KomaYomi-docs/remote-backup">Backup reference</a> — storage JSON and file-level details.</li><li><a href="/KomaYomi-docs/guide/gallery">Library &amp; Import</a> — folder rules still apply to the mirror.</li><li><a href="/KomaYomi-docs/server/error-codes">Server &amp; CLI Message Codes</a> — <code>ERR_REMOTE_UNAVAILABLE</code>, <code>ERR_THUMB_FETCH_FAILED</code>.</li></ul>',6))])}const T=n(p,[["render",g]]);export{v as __pageData,T as default};
